steps.input:
n=19
# Input markers and colored cross centers, all zero-indexed.
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
markers={(2,6),(4,6),(3,5),(3,7), (3,13),(5,13),(4,12),(4,14), (11,14),(13,14),(12,13),(12,15), (13,3),(15,3),(14,2),(14,4), (9,8),(11,8),(10,7),(10,9)}
own={ (r,c): {(r-1,c),(r+1,c),(r,c-1),(r,c+1)} for r,c,_ in centers }
# Each 3 marker stops rays from a different cross; arms of the originating cross are traversed.
H=[[0]*n for _ in range(n)]; V=[[0]*n for _ in range(n)]
for r,c,color in centers:
    for dc in (-1,1):
        j=c
        while 0<=j<n:
            if (r,j) in markers and (r,j) not in own[(r,c)]: break
            H[r][j]=color; j+=dc
    for dr in (-1,1):
        i=r
        while 0<=i<n:
            if (i,c) in markers and (i,c) not in own[(r,c)]: break
            V[i][c]=color; i+=dr
out=[[V[i][j] or H[i][j] for j in range(n)] for i in range(n)]
for r,c in markers: out[r][c]=3
import json
print(json.dumps(out,separators=(',',':')))

n=19
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
markers={(2,6),(4,6),(3,5),(3,7), (3,13),(5,13),(4,12),(4,14), (11,14),(13,14),(12,13),(12,15), (13,3),(15,3),(14,2),(14,4), (9,8),(11,8),(10,7),(10,9)}
empty_centers=[(10,8)]
H=[[0]*n for _ in range(n)]; V=[[0]*n for _ in range(n)]
for r,c,v in centers:
    for j in range(n): H[r][j]=v
for r,c,v in centers:
    for i in range(n): V[i][c]=v
out=[[V[i][j] or H[i][j] for j in range(n)] for i in range(n)]
for r,c in empty_centers:
    for i in range(n):
        if any(rr==i for rr,cc,v in centers) and (i,c) not in markers:
            out[i][c]=0
for r,c in markers: out[r][c]=3
import json
print(json.dumps(out,separators=(',',':')))

n=19
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
blank=(10,8)
allcrosses=[(r,c) for r,c,v in centers]+[blank]
markers={}
for k,(r,c) in enumerate(allcrosses):
    for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
        markers.setdefault(p,set()).add(k)
out=[[0]*n for _ in range(n)]
H=[[0]*n for _ in range(n)]; V=[[0]*n for _ in range(n)]
for k,(r,c,v) in enumerate(centers):
    own={(r-1,c),(r+1,c),(r,c-1),(r,c+1)}
    for dr,dc,arr in [(0,-1,H),(0,1,H),(-1,0,V),(1,0,V)]:
        i,j=r,c
        while 0<=i<n and 0<=j<n:
            if (i,j) in markers and k not in markers[(i,j)] and (i,j) not in own:
                break
            arr[i][j]=v
            i+=dr; j+=dc
for i in range(n):
    for j in range(n): out[i][j]=V[i][j] or H[i][j]
for p in markers: out[p[0]][p[1]]=3
assert len(out)==19 and all(len(row)==19 for row in out)
