n=19
centers=[(3,6,8),(4,13,4),(12,14,1),(14,3,2)]
crosses=[(3,6),(4,13),(12,14),(14,3),(10,8)]
center_owner={p:i for i,p in enumerate(crosses)}
arm_owner={}
for k,(r,c) in enumerate(crosses):
    for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)): arm_owner[p]=k
h=[[0]*n for _ in range(n)]; vgrid=[[0]*n for _ in range(n)]
for k,(r,c,val) in enumerate(centers):
    for dr,dc,layer in ((0,-1,h),(0,1,h),(-1,0,vgrid),(1,0,vgrid)):
        i,j=r,c
        while 0<=i<n and 0<=j<n:
            # Continue through own cross arms; other crosses' arms and centers are opaque.
            if ((i,j) in arm_owner and arm_owner[(i,j)]!=k) or ((i,j) in center_owner and center_owner[(i,j)]!=k): break
            layer[i][j]=val
            i+=dr; j+=dc
out=[[vgrid[i][j] or h[i][j] for j in range(n)] for i in range(n)]
for r,c in arm_owner: out[r][c]=3
